-- hh_products: catalog products for hhmedicalsupply.com. id is text (not
-- uuid) for the same reason as 0015-0018. Depends on 0016 (hh_categories)
-- and 0018 (hh_product_categories).
--
-- `category` is the product's primary category slug; a product can also sit
-- in extra categories via hh_product_categories. price is null when the
-- product is "Call for pricing" (see price_label).

create table hh_products (
  id text primary key default gen_random_uuid()::text,
  name text not null,
  slug text not null unique,
  category text references hh_categories(slug) on update cascade on delete set null,
  short_description text,
  description text,
  features jsonb not null default '[]'::jsonb,
  specifications jsonb not null default '{}'::jsonb,
  price numeric(10, 2),
  price_label text,
  product_type text,
  product_url text,
  image_url text,
  image_candidates jsonb not null default '[]'::jsonb,
  verification_status text,
  notes text,
  is_active boolean not null default true,
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  featured boolean not null default false
);
create index hh_products_category_idx on hh_products(category);
create index hh_products_sort_order_idx on hh_products(sort_order);

alter table hh_products enable row level security;
create policy "authenticated full access" on hh_products
  for all using (auth.role() = 'authenticated') with check (auth.role() = 'authenticated');

-- hh_products (99 rows)

-- Now that the products exist, tie the join table to them (every
-- product_id in 0018 is present above).
alter table hh_product_categories
  add constraint hh_product_categories_product_id_fkey
  foreign key (product_id) references hh_products(id) on update cascade on delete cascade;
