insert into hh_products (id, name, slug, category, short_description, description, features, specifications, price, price_label, product_type, product_url, image_url, image_candidates, verification_status, notes, is_active, sort_order, created_at, updated_at, featured) values
  ('a092fc07-db52-4412-a0a5-d07ac49edddf', 'Advantage Therapeutic Homecare Foam Mattress', 'advantage-therapeutic-homecare-foam-mattress', 'bedroom', 'Therapeutic foam mattress designed for homecare use, pressure redistribution, and everyday patient comfort.', 'A premium homecare foam mattress with a polyurethane core that decompresses quickly and provides latex-like comfort without latex allergens. Its fluid-resistant nylon cover is designed to reduce shear and friction, support pressure redistribution, and simplify cleaning.', '["Pressure-redistributing polyurethane foam core","Fluid-resistant nylon cover","Anti-shear and anti-friction surface","Flippable construction","Designed for pressure-sore prevention and homecare use","Meets 16 CFR Part 1633 flammability requirements"]'::jsonb, '{"dimensions":"80 x 36 x 6 in","material":"Polyurethane foam with nylon cover","weight":"9.6 lb"}'::jsonb, '250.00', '$250.00', 'purchase', 'https://hhmedicalsupply.com/product/advantage-therapeutic-homecare-foam-mattress/', 'https://trfaedilmjxpgbwadjgp.supabase.co/storage/v1/object/public/product-images/advantage_therapeutic_homecare_foam_mattress.jpg', '[]'::jsonb, 'verified_hh_product_page', 'Exact H&H product page and specifications were found. Image URL should be resolved from the page metadata.', true, 0, '2026-07-16 22:18:04.55398+00', '2026-07-20 18:57:12.742958+00', false),
  ('d73e0be8-18c9-453d-8dc6-66d9ab8a7549', 'Alternating Pressure Pads Mattress and Pump (APP)', 'alternating-pressure-pads-mattress-and-pump-app', 'bedroom', 'Alternating-pressure pad and pump system designed to improve pressure distribution for patients with limited mobility.', 'An alternating-pressure overlay system that uses an electric pump to inflate and deflate air cells in cycles. It is intended to improve comfort and redistribute pressure for patients who spend extended periods in bed.', '["Alternating air-cell pressure cycle","Adjustable pump pressure","Lightweight mattress overlay","Designed for use over a standard medical mattress","Supports pressure-injury prevention protocols"]'::jsonb, '{"exact_model":"Not confirmed from indexed H&H page","system_components":"Pressure pad and electric pump"}'::jsonb, null, 'Call for pricing', 'purchase_or_rental', 'https://hhmedicalsupply.com/product/alternating-pressure-pads-mattress-and-pump-app/', 'https://trfaedilmjxpgbwadjgp.supabase.co/storage/v1/object/public/product-images/alternating_pressure_pads_mattress_and_pump_app.jpg', '["alternative pressure pad app hhmedicalsupplyu"]'::jsonb, 'hh_catalog_confirmed_details_need_review', 'Listed by H&H, but the exact product page was not reliably retrievable. Verify model, dimensions, weight capacity, and price.', true, 10, '2026-07-16 22:18:04.55398+00', '2026-07-20 18:57:12.742958+00', false),
  ('4d55f2cb-fd63-41e8-b0b6-26979e07b2b6', 'Bed Cradle and Foot Support', 'bed-cradle-and-foot-support', 'bedroom', 'Bed-mounted support that keeps sheets and blankets away from sensitive feet and lower legs.', 'A removable steel bed cradle designed to lift bedding away from a patient''s feet and lower legs. It can improve comfort for patients with wounds, burns, sensitivity, or limited lower-extremity mobility.', '["Keeps blankets and sheets off the feet","Sturdy removable steel frame","Clamps or slides securely beneath the mattress","Compact, multi-piece design for storage","Compatible with many standard hospital and homecare beds"]'::jsonb, '{"exact_model":"Not confirmed from indexed H&H page","typical_height":"Approximately 21.5-24 in","typical_length":"Approximately 36 in"}'::jsonb, null, 'Call for pricing', 'purchase', 'https://hhmedicalsupply.com/product/bed-cradle-and-foot-support/', 'https://trfaedilmjxpgbwadjgp.supabase.co/storage/v1/object/public/product-images/bed_cradle_and_foot_support.jpg', '[]'::jsonb, 'hh_catalog_confirmed_external_specs', 'H&H listing confirmed. Dimensions are representative and must be checked against the stocked model.', true, 20, '2026-07-16 22:18:04.55398+00', '2026-07-20 18:57:12.742958+00', false),
  ('9e27adec-447a-4746-a8b3-064fa983aaeb', 'Bed Rails — Half Rails or Full Rails', 'bed-rails-half-rails-or-full-rails', 'bedroom', 'Hospital-bed safety rails available in half-length or full-length configurations.', 'Bed rails designed to assist with positioning, provide a handhold, and help reduce accidental rolling from a compatible hospital or homecare bed. Half rails offer easier entry and exit, while full rails provide more extensive bedside coverage.', '["Available in half-length or full-length styles","Provides positioning and transfer assistance","Designed for compatible medical bed frames","Durable metal construction","Easy-release or adjustable mechanisms may vary by model"]'::jsonb, '{"compatibility":"Must be confirmed with the specific bed frame and mattress","configuration":"Half rails or full rails"}'::jsonb, null, 'Call for pricing', 'purchase_or_rental', 'https://hhmedicalsupply.com/product/bed-rails-half-rails-or-full-rails/', 'https://trfaedilmjxpgbwadjgp.supabase.co/storage/v1/object/public/product-images/bed_rails_half_rails_or_full_rails.jpg', '[]'::jsonb, 'hh_catalog_confirmed_details_need_review', 'Do not treat rails as universally compatible. Confirm the bed make, model, mattress thickness, and entrapment-risk requirements.', true, 30, '2026-07-16 22:18:04.55398+00', '2026-07-20 18:57:12.742958+00', false),
  ('55777bee-2d99-424f-8fe4-933fd8513f40', 'Bedside Safety Fall Mat', 'bedside-safety-fall-mat', 'bedroom', 'Low-profile bedside safety mat designed to help cushion the impact of an accidental fall.', 'A shock-absorbing floor mat placed beside a bed to help reduce injury risk if a patient rolls or falls from bed. A low-profile design and beveled edges help limit trip hazards for caregivers and mobility equipment.', '["Shock-absorbing foam construction","Low-profile bedside placement","Beveled edges to reduce trip hazards","Slip-resistant bottom surface","Easy-to-clean cover"]'::jsonb, '{"exact_dimensions":"Not confirmed from indexed H&H page","image_reference":"Safety Fall Matt"}'::jsonb, null, 'Call for pricing', 'purchase_or_rental', 'https://hhmedicalsupply.com/product/bedside-safety-fall-mat/', 'https://trfaedilmjxpgbwadjgp.supabase.co/storage/v1/object/public/product-images/bedside_safety_fall_mat.jpg', '["Safety Fall Matt"]'::jsonb, 'hh_catalog_confirmed_details_need_review', 'H&H catalog spelling appears as ''Matt'' in some locations. Recommended display name is ''Mat.''', true, 40, '2026-07-16 22:18:04.55398+00', '2026-07-20 18:57:12.742958+00', false),
  ('d71eb0d3-fcb5-4496-9a4c-ab5a9c60c9bb', 'Deluxe Overbed Table — Wood Laminate', 'deluxe-over-bed-table-wood-laminated', 'bedroom', 'Height-adjustable overbed table with a durable walnut wood-grain laminate top.', 'A mobile overbed table designed for meals, reading, personal items, and everyday bedside activities. It features a welded steel base, smooth casters, and a touch-handle height adjustment.', '["Walnut wood-grain laminate tabletop","Touch-handle height adjustment","Welded steel base","Mobile caster base","Rear glide cap for stability"]'::jsonb, '{"dimensions":"15.2 x 30 x 43 in","height_adjustment":"28-40 in","weight":"21 lb"}'::jsonb, '99.99', '$99.99', 'purchase', 'https://hhmedicalsupply.com/product/deluxe-over-bed-table-wood-laminated/', 'https://trfaedilmjxpgbwadjgp.supabase.co/storage/v1/object/public/product-images/deluxe_overbed_table_wood_laminate.jpg', '[]'::jsonb, 'verified_hh_product_page', 'Exact H&H product page and pricing were found.', true, 50, '2026-07-16 22:18:04.55398+00', '2026-07-20 18:57:12.742958+00', false),
  ('69ed3a6c-ff30-41ec-bea3-2bd5eed28427', 'Drive Medical Innerspring Mattress', 'drive-medical-inner-spring-mattress', 'bedroom', 'Hospital-bed innerspring mattress with foam cushioning and a waterproof healthcare cover.', 'A Drive Medical innerspring mattress designed for standard hospital and homecare beds. Premium cotton and high-density urethane foam are layered over the innerspring system, while a waterproof vinyl cover supports routine cleaning.', '["High-quality innerspring construction","Cotton and high-density urethane foam cushioning","Waterproof, antibacterial, and antistatic vinyl cover","Side vents for airflow","Designed for standard 36-inch medical beds"]'::jsonb, '{"dimensions":"80 x 36 x 6 in","representative_model":"Drive Medical 15006","weight_capacity":"Approximately 250-300 lb, depending on exact model"}'::jsonb, null, 'Call for pricing', 'purchase_or_rental', 'https://hhmedicalsupply.com/product/drive-medical-inner-spring-mattress/', 'https://trfaedilmjxpgbwadjgp.supabase.co/storage/v1/object/public/product-images/drive_medical_innerspring_mattress.jpg', '[]'::jsonb, 'hh_catalog_confirmed_external_specs', 'Model 15006 specifications are representative. Confirm the exact H&H SKU before publishing capacity or warranty.', true, 60, '2026-07-16 22:18:04.55398+00', '2026-07-20 18:57:12.742958+00', false),
  ('ff4fcbda-815e-42f9-b215-25c8ee0cca8d', 'Egg Crate Mattress', 'egg-crate-mattress', 'bedroom', 'Convoluted foam mattress overlay that adds cushioning, ventilation, and pressure distribution.', 'A medical-grade convoluted foam overlay with an egg-crate surface that increases airflow and helps distribute body pressure. It is commonly placed over an existing mattress for additional comfort.', '["Convoluted egg-crate foam surface","Improves airflow beneath the patient","Adds cushioning to an existing mattress","Lightweight and easy to position","Supports pressure redistribution"]'::jsonb, '{"exact_model":"Not confirmed from indexed H&H page","typical_size":"Approximately 36 x 76 in","typical_thickness":"2-3 in"}'::jsonb, null, 'Call for pricing', 'purchase', 'https://hhmedicalsupply.com/product/egg-crate-mattress/', 'https://trfaedilmjxpgbwadjgp.supabase.co/storage/v1/object/public/product-images/egg_crate_mattress.jpg', '[]'::jsonb, 'hh_catalog_confirmed_external_specs', 'Confirm actual dimensions and foam density for the stocked item.', true, 70, '2026-07-16 22:18:04.55398+00', '2026-07-20 18:57:12.742958+00', false),
  ('9b568b65-44bf-4a88-86b3-528c37989d87', 'Extension Kit for Full Electric Bed', 'extension-kit-for-full-electric-bed', 'bedroom', 'Bed extension kit that adds approximately four inches to a compatible full-electric bed.', 'An extension accessory for compatible Drive Medical full-electric beds. It increases the usable bed length for taller patients and is designed for straightforward installation.', '["Adds approximately 4 inches to bed length","Strong aluminum construction","Designed for simple installation","Made for compatible Drive Medical bed frames"]'::jsonb, '{"dimensions":"47 x 5 x 2 in","material":"Aluminum","representative_capacity":"450 lb","representative_model":"Drive Medical 15005EXTKIT","weight":"9.5 lb"}'::jsonb, null, 'Call for pricing', 'purchase', 'https://hhmedicalsupply.com/product/extension-kit-for-full-electric-bed/', 'https://trfaedilmjxpgbwadjgp.supabase.co/storage/v1/object/public/product-images/extension_kit_for_full_electric_bed.jpg', '[]'::jsonb, 'hh_catalog_confirmed_external_specs', 'Verify bed-model compatibility before sale or installation.', true, 80, '2026-07-16 22:18:04.55398+00', '2026-07-20 18:57:12.742958+00', false),
  ('cfbc94f9-b46a-47bb-9811-1fcf214e9465', 'Full Electric Bed Complete Set', 'full-electric-bed-complete-set', 'bedroom', 'Complete full-electric hospital bed rental with mattress and safety rails.', 'A complete homecare bed package with powered controls for the head, foot, and overall bed height. The rental set is intended to include the bed frame, a compatible mattress, and safety rails, with delivery and setup coordinated by H&H Medical Supply.', '["Electric head and foot positioning","Powered bed-height adjustment","Includes compatible mattress","Includes safety rails","Home delivery and professional setup","Tool-free or simplified assembly, depending on model"]'::jsonb, '{"exact_model_and_capacity":"Must be confirmed","typical_deck_height":"Approximately 15.5-21.5 in","typical_sleep_surface":"36 x 80 in"}'::jsonb, null, 'Call for rental pricing', 'rental', 'https://hhmedicalsupply.com/product/full-electric-bed-set-rental/', 'https://trfaedilmjxpgbwadjgp.supabase.co/storage/v1/object/public/product-images/full-electric-hospital-bed.png', '["Drive Full Electric Bed Set"]'::jsonb, 'hh_catalog_confirmed_details_need_review', 'Confirm rental term, bed model, capacity, mattress type, and rail configuration.', true, 90, '2026-07-16 22:18:04.55398+00', '2026-07-17 23:36:09.444896+00', true),
  ('38830eea-5a13-4183-afda-e615aa237fa7', 'Low Air Loss Mattress (LAL)', 'alternating-pressure-and-low-air-loss-mattress', 'bedroom', 'Alternating-pressure and low-air-loss mattress system for advanced pressure redistribution.', 'A therapeutic mattress system combining alternating pressure and low-air-loss functions. Fourteen independent air bladders cycle on a ten-minute interval, while a foam safety base provides backup support during a power outage.', '["Alternating-pressure and low-air-loss therapy","Fourteen independent 5-inch air bladders","Three-inch foam safety base","Ten-minute alternating cycle","Audible and visual low-pressure alarms","CPR valve","Removable fluid-resistant quilted nylon cover"]'::jsonb, '{"air_cells":"14","cycle_time":"10 minutes","dimensions":"78 x 35 x 5 in","listed_weight":"2.2 lb"}'::jsonb, null, 'Call for pricing', 'purchase_or_rental', 'https://hhmedicalsupply.com/product/alternating-pressure-and-low-air-loss-mattress/', 'https://trfaedilmjxpgbwadjgp.supabase.co/storage/v1/object/public/product-images/low_air_loss_mattress_lal.jpg', '["81DuH2zuYYL._AC_SL1500_","71AY2ihblqL._AC_SL1500_"]'::jsonb, 'verified_hh_product_page', 'Exact H&H page was found. Verify the unusually low listed product weight before publication.', true, 100, '2026-07-16 22:18:04.55398+00', '2026-07-20 18:57:12.742958+00', false),
  ('8708210a-efe9-443c-891c-e698e7b758cc', 'Semi Electric Bed Complete Set', 'semi-electric-bed-complete-set', 'bedroom', 'Semi-electric hospital bed package with powered head and foot positioning, mattress, and safety rails.', 'A complete homecare bed set with electric controls for head and foot positioning and manual bed-height adjustment. The package includes a compatible mattress and safety rails for delivery and setup in the patient''s residence.', '["Electric head and foot positioning","Manual bed-height adjustment","Includes mattress","Includes safety rails","Designed for homecare delivery and setup"]'::jsonb, '{"exact_model_and_capacity":"Must be confirmed","typical_sleep_surface":"36 x 80 in"}'::jsonb, null, 'Call for pricing', 'purchase_or_rental', 'https://hhmedicalsupply.com/product/semi-electric-bed-complete-set/', 'https://trfaedilmjxpgbwadjgp.supabase.co/storage/v1/object/public/product-images/semi_electric_bed_complete_set.jpg', '["Semi Electric Bed From H&H Medical Supply"]'::jsonb, 'hh_catalog_confirmed_details_need_review', 'Confirm whether this listing is for purchase, rental, or both, and verify the included mattress and rail type.', true, 110, '2026-07-16 22:18:04.55398+00', '2026-07-20 18:57:12.742958+00', false),
  ('2e6e5ed5-1d35-4165-88f9-f9760bd8223b', 'Heavy Duty Deluxe Bariatric Bedside Commode', 'am-heavy-duty-deluxe-bariatric-bedside-commode', 'bathroom', 'Extra-wide steel bedside commode with drop arms and a high weight capacity.', 'A heavy-duty bariatric commode built with a powder-coated steel frame, padded drop arms, and a snap-on seat. It includes a large-capacity bucket and is designed to support safer bedside toileting and transfers.', '["Powder-coated steel frame","Padded drop arms","Snap-on seat","12-quart bucket with cover","Extra-wide seating area","Listed 1,000 lb weight capacity"]'::jsonb, '{"listed_product_weight":"21 lb","overall_width":"26.25 in","seat":"23.25 W x 18.5 D in","seat_height":"17.5-22 in","width_between_arms":"25.75 in"}'::jsonb, null, 'Call for pricing', 'purchase', 'https://hhmedicalsupply.com/product/am-heavy-duty-deluxe-bariatric-bedside-commode/', 'https://trfaedilmjxpgbwadjgp.supabase.co/storage/v1/object/public/product-images/heavy_duty_deluxe_bariatric_bedside_commode.jpg', '["71mwuoy5xHL._AC_SL1500_","71UKQRsZxZL._AC_SL1500_","61gofoXHAIL._AC_SL1500_","71kZStO27IL._AC_SL1500_"]'::jsonb, 'verified_hh_product_page', 'The H&H page contains conflicting product-weight information. Core dimensional specifications are taken from the feature section.', true, 120, '2026-07-16 22:18:04.55398+00', '2026-07-20 18:58:40.933691+00', false),
  ('b19ddb2f-5a18-489f-9b00-2ca0c0791139', 'Deluxe Bedside Commode', 'deluxe-bedside-commode', 'bathroom', 'Height-adjustable bedside commode for use beside the bed or over a toilet.', 'A versatile bedside commode with a removable bucket, supportive armrests, and an adjustable frame. It may be used as a standalone commode, a toilet safety frame, or an elevated seat over a compatible toilet.', '["Multi-purpose bedside or over-toilet use","Height-adjustable frame","Removable bucket with lid","Supportive armrests","Easy-clean seat and frame"]'::jsonb, '{"capacity":"Verify before publication","exact_model":"Not confirmed from indexed H&H page"}'::jsonb, '99.99', '$99.99 shown in H&H featured catalog', 'purchase', 'https://hhmedicalsupply.com/product/deluxe-bedside-commode/', 'https://trfaedilmjxpgbwadjgp.supabase.co/storage/v1/object/public/product-images/deluxe_bedside_commode.jpg', '["Bedside Commode"]'::jsonb, 'hh_catalog_confirmed_details_need_review', 'Featured H&H catalog showed $99.99, but the exact page and model specifications were not retrieved.', true, 130, '2026-07-16 22:18:04.55398+00', '2026-07-20 18:58:40.933691+00', true),
  ('2dfe2ed2-c0fc-4aca-9f3e-f898fa234333', 'High-Durability Transfer Shower Bench', 'high-durable-transfer-bench', 'bathroom', 'Transfer bench designed to support seated movement into and out of a bathtub or shower.', 'A bath transfer bench that extends across the tub wall, allowing the user to sit before moving into the bathing area. Its corrosion-resistant frame, textured seating surface, and slip-resistant feet are intended to improve stability during transfers.', '["Tub-transfer bench design","Corrosion-resistant aluminum frame","Height-adjustable legs","Slip-resistant feet","Textured seat with back support","Drainage openings"]'::jsonb, '{"capacity":"Verify before publication","exact_model":"Not confirmed from indexed H&H page"}'::jsonb, null, 'Call for pricing', 'purchase', 'https://hhmedicalsupply.com/product/high-durable-transfer-bench/', 'https://trfaedilmjxpgbwadjgp.supabase.co/storage/v1/object/public/product-images/high_durability_transfer_shower_bench.jpg', '[]'::jsonb, 'hh_catalog_confirmed_details_need_review', 'H&H catalog title appears as ''High Durable Transfer Bench.'' Verify exact dimensions and weight capacity.', true, 140, '2026-07-16 22:18:04.55398+00', '2026-07-20 18:58:40.933691+00', false),
  ('ac137355-878c-4799-8168-a3b31456f20f', 'Shower Chair with Back', 'shower-chair-with-back', 'bathroom', 'Height-adjustable shower chair with back support and a rust-resistant frame.', 'A lightweight bath chair that provides seated support during showering. The molded seat and back are designed for drainage and cleaning, while angled legs and slip-resistant tips improve stability.', '["Molded seat and back with hand grips","Anodized aluminum rust-resistant frame","Height-adjustable legs","Slip-resistant feet","Drainage openings"]'::jsonb, '{"representative_capacity":"250 lb","representative_seat_depth":"12 in","representative_seat_height":"13-20 in","representative_seat_width":"19 in"}'::jsonb, null, 'Call for pricing', 'purchase', 'https://hhmedicalsupply.com/product/shower-chair-with-back/', 'https://trfaedilmjxpgbwadjgp.supabase.co/storage/v1/object/public/product-images/shower_chair_with_back.jpg', '[]'::jsonb, 'hh_catalog_confirmed_external_specs', 'Dimensions are representative of a common Medline-style model. Verify H&H''s exact stocked chair.', true, 150, '2026-07-16 22:18:04.55398+00', '2026-07-20 18:58:40.933691+00', false),
  ('909fc449-2d12-4368-bbb2-1d73e017bb0a', 'Raised Toilet Seat — Slip-Resistant', 'raiser-toilet-seat-slip-resistant', 'bathroom', 'Raised toilet seat designed to reduce the effort required to sit and stand.', 'A slip-resistant toilet-seat riser that increases the seating height of a compatible toilet. It is intended to assist users with limited hip, knee, or lower-body mobility.', '["Adds height to a standard toilet","Slip-resistant contact points","Designed for easier sitting and standing","Easy-clean molded surface","Tool-free or locking installation, depending on model"]'::jsonb, '{"capacity":"Verify before publication","compatibility":"Confirm toilet bowl shape and mounting style","exact_height":"Not confirmed"}'::jsonb, null, 'Call for pricing', 'purchase', 'https://hhmedicalsupply.com/product/raiser-toilet-seat-slip-resistant/', 'https://trfaedilmjxpgbwadjgp.supabase.co/storage/v1/object/public/product-images/raised_toilet_seat_slip_resistant.jpg', '[]'::jsonb, 'hh_catalog_confirmed_details_need_review', 'Original catalog title uses ''Raiser.'' The customer-facing name has been normalized to ''Raised Toilet Seat.''', true, 170, '2026-07-16 22:18:04.55398+00', '2026-07-20 18:58:40.933691+00', false),
  ('1cdefb41-2c79-4d80-9fe5-0f418ae80530', 'Drive Four-Wheel Walker Rollator', 'drive-front-wheel-walker', 'mobility-aids', 'Four-wheel rollator with a padded seat, storage pouch, backrest, and hand brakes.', 'A Drive Medical four-wheel rollator designed for walking support and convenient seated rest. It includes a padded seat, a zippered storage pouch, a removable backrest, and loop-lock hand brakes.', '["Seamless padded seat","Zippered pouch beneath the seat","Removable hinged padded backrest","Six-inch non-marring casters","Loop-lock hand brakes","Adjustable ergonomic handles"]'::jsonb, '{"listed_weight":"17 lb","site_dimensions":"64 x 59 x 78.1 (site units appear inconsistent)","wheel_size":"6 in"}'::jsonb, null, 'Sale — price not shown in indexed result', 'purchase', 'https://hhmedicalsupply.com/product/drive-front-wheel-walker/', 'https://trfaedilmjxpgbwadjgp.supabase.co/storage/v1/object/public/product-images/drive-medical-four-wheel-walker-rollator.png', '[]'::jsonb, 'verified_hh_product_page', 'The H&H URL slug says front-wheel walker, but the page content describes a four-wheel rollator. Verify slug and units before migration.', true, 180, '2026-07-16 22:18:04.55398+00', '2026-07-17 23:30:30.872224+00', true),
  ('605dbbb9-77c6-4f6f-96aa-374444ae11eb', 'Drive Offset Handle Single-Point Cane', 'drive-offset-handle-single-point-cane', 'mobility-aids', 'Height-adjustable aluminum cane with an ergonomic offset handle and foam grip.', 'A lightweight Drive Medical single-point cane with an offset handle that places the user''s weight over the base for improved balance. It includes a foam grip, wrist strap, and locking ring.', '["Ergonomic offset handle","Comfortable foam grip","Included wrist strap","Anodized aluminum shaft","Locking ring for added security","Height-adjustable design"]'::jsonb, '{"height_adjustment":"30-39 in","listed_capacity":"250 lb","material":"Anodized aluminum"}'::jsonb, '19.99', '$19.99', 'purchase', 'https://hhmedicalsupply.com/product/drive-offset-handle-single-point-cane/', 'https://trfaedilmjxpgbwadjgp.supabase.co/storage/v1/object/public/product-images/drive_offset_handle_single_point_cane.jpg', '["rtl10372bc_2_1","rtl10372bk-c_3"]'::jsonb, 'verified_hh_product_page', 'The H&H page also mentions 300 lb in body copy. The listed feature specification is 250 lb; verify the exact model.', true, 190, '2026-07-16 22:18:04.55398+00', '2026-07-20 19:01:07.375057+00', false),
  ('7e67dee3-1cce-4a4c-a912-b10c7e4ade90', 'Front-Wheel Walker', 'front-wheel-walker', 'mobility-aids', 'Folding walker with front wheels for stable, assisted ambulation.', 'A lightweight front-wheel walker designed to provide support while allowing smoother forward movement than a standard pickup walker. It typically includes push-button folding, adjustable handles, and rear glide caps or tips.', '["Two front wheels","Folding aluminum frame","Height-adjustable handles","Push-button folding mechanism","Rear glide caps or rubber tips","Lightweight, portable construction"]'::jsonb, '{"capacity":"Verify before publication","exact_model":"Not confirmed from indexed H&H page"}'::jsonb, null, 'Call for pricing', 'purchase_or_rental', 'https://hhmedicalsupply.com/product/front-wheel-walker/', 'https://trfaedilmjxpgbwadjgp.supabase.co/storage/v1/object/public/product-images/front_wheel_walker.jpg', '["Front Wheel Walker rental"]'::jsonb, 'hh_catalog_confirmed_details_need_review', 'Do not confuse this product with the four-wheel rollator page that currently uses a similar H&H URL slug.', true, 200, '2026-07-16 22:18:04.55398+00', '2026-07-20 19:01:07.375057+00', false),
  ('9997da22-0678-4482-8614-e4f5fa0cc506', 'Patient Hoyer Lift', 'patient-hoyer-lift', 'mobility-aids', 'Portable hydraulic patient lift rental for caregiver-assisted transfers.', 'A portable patient lift designed to assist caregivers with transfers between a bed, wheelchair, commode, or other supported surface. Its rotating pump handle and low-friction casters are designed for controlled operation in homecare environments.', '["Padded swivel bar","Compatible with multiple sling styles","Rotating hydraulic pump handle","Low-friction casters","Steel construction","Disassembles for transport and storage"]'::jsonb, '{"brand":"Invacare listed on H&H page","capacity":"Verify exact rental model","listed_weight":"75 lb","site_dimensions":"52 x 28 x 14 in"}'::jsonb, null, 'Call for monthly rental pricing', 'rental', 'https://hhmedicalsupply.com/product/patient-hoyer-lift-monthly-rental/', 'https://trfaedilmjxpgbwadjgp.supabase.co/storage/v1/object/public/product-images/patient_hoyer_lift.jpg', '[]'::jsonb, 'verified_hh_product_page', 'The H&H description says the lift is less than 70 lb, while additional information lists 75 lb.', true, 210, '2026-07-16 22:18:04.55398+00', '2026-07-20 19:01:07.375057+00', false),
